// Overengineered version
pub fn process_data<T: Clone + std::fmt::Display>(data: &[T]) -> Result<Vec<String>, std::io::Error> {
    let mut result = Vec::new();
    for item in data {
        let processed = match std::fs::read_to_string(item.to_string()) {
            Ok(content) => content.lines().filter(|l| !l.is_empty()).map(String::from).collect(),
            Err(e) => {
                eprintln!("Error processing {}: {}", item, e);
                Vec::new()
            }
        };
        result.extend(processed);
    }
    Ok(result)
}

// Simpler version
pub fn process_data<T: Clone + std::fmt::Display>(data: &[T]) -> Vec<String> {
    let mut result = Vec::new();
    for item in data {
        let content = std::fs::read_to_string(item.to_string()).unwrap_or_default();
        result.extend(content.lines().filter(|l| !l.is_empty()).map(String::from));
    }
    result
}
```

